def togaf_check_code_coverage(codes, mandatory=None):
    REQUIRED = ['BIZ-CAP-MAP', 'GAP-ANALYSIS']
    if mandatory is None:
        mandatory = REQUIRED
    known = set(['ADM-PRELIMINARY', 'DISCOVERY', 'BIZ-CAP-MAP', 'APP-INVENTORY', 'APP-RATIONAL', 'GAP-ANALYSIS', 'TRANS-ARCH', 'ARCH-BOARD', 'ARCH-CHANGE', 'ARCH-REPO', 'DATA-ARCH', 'TECH-ARCH'])
    cited = set(codes) if isinstance(codes, list) else set()
    missing = [c for c in mandatory if c not in cited]
    unknown = [c for c in sorted(cited) if c not in known]
    total = len(known)
    covered = len(cited & known)
    return {
        'valid': not missing and not unknown,
        'missing': missing,
        'unknown': unknown,
        'coverage_report': {
            'total_codes': total,
            'covered_codes': covered,
            'coverage_pct': round(100.0 * covered / total, 1) if total else 0.0,
        },
    }

def togaf_check_transition_plan(work_packages, capability_gaps):
    problems = []
    packages = work_packages if isinstance(work_packages, list) else []
    gaps = capability_gaps if isinstance(capability_gaps, list) else []
    closed = set()
    for i, wp in enumerate(packages):
        if not isinstance(wp, dict):
            problems.append('work_packages[%d] is not an object' % i)
            continue
        if not wp.get('id') or not wp.get('name'):
            problems.append('work_packages[%d] missing id/name' % i)
        closes = wp.get('closes')
        if not closes:
            problems.append('work_package %s has no closes field' % wp.get('id'))
        else:
            closed.add(closes)
    gap_set = set(gaps)
    orphans = sorted(closed - gap_set)
    if orphans:
        problems.append('capabilities closed but not in capability_gaps: %s' % orphans)
    return {
        'valid': not problems,
        'problems': problems,
        'work_packages': len(packages),
        'gap_trace': {
            'gaps_declared': len(gap_set),
            'gaps_closed': len(closed & gap_set),
            'unclosed_gaps': sorted(gap_set - closed),
        },
    }
